/* === CENTERING WRAPPER === */
.print-format-container {
    display: table;
    width: 100%;
    height: 100%;
}

.print-format {
    display: table-cell;
    vertical-align: middle;
    text-align: center; /* centers inline-block child */
    padding: 0;
    background-color: transparent;
}

.print-format > .content-wrapper {
    display: inline-block;
    text-align: right; /* restore RTL alignment inside */
    direction: rtl;
    width: 90%;
    max-width: 160mm;
    padding: 10px;
    background-color: rgba(255, 255, 255, 0.85); /* optional: improve readability */
    border-radius: 8px;
}

