}

.header .paragraph {
    font-size: 18px;
    margin: 3px 0;
    font-weight: bold;
}

.header .header-left .paragraph,
.header .left .paragraph {
    text-align: left;
    direction: ltr;
}

.header img {
    margin: 0 auto;
