.main-heading .title {
    text-align: center;
    color: #4472c4;
    font-size: 24px;
    font-weight: bold;
    margin: 25px 0 15px;
    text-decoration: underline;
}

/* --- Personal Photo --- */
.personal-image {
    text-align: center;
    margin: 15px 0;
}

.personal-image img {
    width: 100px;
    height: auto;
    border: 2px solid #ddd;
    border-radius: 8px;
    box-shadow: 0 2px 5px rgba(0,0,0,0.1);
}

/* --- Section Styling --- */
.sub-heading {
    background-color: #f0f8ff;
    border: 1px solid #4472c4;
    padding: 10px 15px;
    margin: 25px 0 15px;
    font-size: 18px;
    font-weight: bold;
    color: #2a5298;
    border-radius: 4px;
    text-align: right;
}

/* --- Paragraphs & Fields --- */
.par {
    font-size: 15px;
    margin: 8px 0;
    padding: 0 10px;
    text-align: right;
}

.par b {
    color: #2a5298;
    min-width: 280px;
    display: inline-block;
}

/* Checkbox styling */
.par span.checkmark {
    margin-left: 5px;
    font-size: 18px;
}

/* --- Child Table Entries --- */
.article-entry {
    margin: 15px 0;
    padding: 10px;
    background-color: #fafafa;
    border-right: 3px solid #4472c4;
    border-radius: 4px;
}

.article-entry .par {
    margin: 4px 0;
}

.article-entry hr {
    margin: 15px 0;
    border-color: #ddd;
}

/* --- Horizontal Rule --- */
hr {
    width: 95%;
    margin: 20px auto;
    border: 0;
    border-top: 1px dashed #ccc;
}

/* --- Notes & Violations --- */
.fifth-section .par {
    background-color: #fff9f9;
    padding: 12px;
    border-right: 3px solid #ff6b6b;
    border-radius: 4px;
    margin: 10px 0;
}

/* --- Signature Area --- */
.signature .paragraph {
    padding: 5px 10px;
    margin-left: 10px;
    font-style: italic;
}

